<div class="page-head"><div><div class="eyebrow">Relationship management</div><h1>Customers</h1><div class="muted">A searchable record of people who enquire and travel with Nature Holidays.</div></div><?php if (Auth::can('customers.manage')): ?><a class="btn" href="<?= nh_e(APP_BASE_PATH) ?>/admin/customers/create">＋ Add customer</a><?php endif ?></div>
